<?php
require_once __DIR__.'/_layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';if($action==='delete'){$s=$pdo->prepare('DELETE FROM rooms WHERE room_id=?');$s->execute([(int)$_POST['room_id']]);flash('success','Room removed.');redirect('rooms.php');}if(in_array($action,['save','new'],true)){$name=trim($_POST['room_name']??'');$type=$_POST['room_type']??'';$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$capacity=(int)($_POST['capacity']??0);$bed=trim($_POST['bed_type']??'');$image=trim($_POST['image']??'');$status=$_POST['status']??'available';if(!$name||!in_array($type,['Deluxe Room','Premium Room','Executive Suite','Presidential Suite'],true)||$price<=0||$capacity<1||!filter_var($image,FILTER_VALIDATE_URL)){$error='Complete all fields with a valid image URL, price and capacity.';}else if($action==='new'){$s=$pdo->prepare('INSERT INTO rooms(room_name,room_type,description,price,capacity,bed_type,image,status) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$name,$type,$description,$price,$capacity,$bed,$image,$status]);flash('success','Room added.');redirect('rooms.php');}else{$s=$pdo->prepare('UPDATE rooms SET room_name=?,room_type=?,description=?,price=?,capacity=?,bed_type=?,image=?,status=? WHERE room_id=?');$s->execute([$name,$type,$description,$price,$capacity,$bed,$image,$status,(int)$_POST['room_id']]);flash('success','Room updated.');redirect('rooms.php');}}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM rooms WHERE room_id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rooms=$pdo->query('SELECT * FROM rooms ORDER BY room_id')->fetchAll();admin_start('Room management');?><?php if($error): ?><p style="color:#a34837"><?= e($error) ?></p><?php endif; ?><div class="panel"><h2><?= $edit?'Edit a room':'Add a room' ?></h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $edit?'save':'new' ?>"><?php if($edit): ?><input type="hidden" name="room_id" value="<?= (int)$edit['room_id'] ?>"><?php endif; ?><div class="form-grid"><div class="form-field"><label>Room name</label><input name="room_name" required value="<?= e($edit['room_name']??'') ?>"></div><div class="form-field"><label>Room type</label><select name="room_type"><?php foreach(['Deluxe Room','Premium Room','Executive Suite','Presidential Suite'] as $t): ?><option <?= ($edit['room_type']??'')===$t?'selected':'' ?>><?= e($t) ?></option><?php endforeach; ?></select></div><div class="form-field"><label>Price per night (₹)</label><input type="number" min="1" step="1" name="price" value="<?= e($edit['price']??'') ?>" required></div><div class="form-field"><label>Guest capacity</label><input type="number" min="1" name="capacity" value="<?= e($edit['capacity']??'2') ?>" required></div><div class="form-field"><label>Bed type</label><input name="bed_type" value="<?= e($edit['bed_type']??'King bed') ?>" required></div><div class="form-field"><label>Availability</label><select name="status"><option value="available">Available</option><option value="maintenance" <?= ($edit['status']??'')==='maintenance'?'selected':'' ?>>Maintenance</option></select></div><div class="form-field wide"><label>Image URL</label><input type="url" name="image" value="<?= e($edit['image']??'') ?>" required></div><div class="form-field wide"><label>Description</label><textarea name="description" required><?= e($edit['description']??'') ?></textarea></div></div><button class="button"><?= $edit?'Save changes':'Add room' ?></button><?php if($edit): ?> <a class="text-link" href="rooms.php">Cancel</a><?php endif; ?></form></div><h2 style="font:25px var(--serif);color:var(--navy);margin-top:32px">All rooms</h2><table class="data-table"><thead><tr><th>Name</th><th>Type</th><th>Price</th><th>Capacity</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rooms as $r): ?><tr><td><?= e($r['room_name']) ?></td><td><?= e($r['room_type']) ?></td><td>₹<?= number_format((float)$r['price']) ?></td><td><?= (int)$r['capacity'] ?></td><td><?= e($r['status']) ?></td><td><a href="?edit=<?= (int)$r['room_id'] ?>">Edit</a> · <form method="post" style="display:inline" onsubmit="return confirm('Delete this room?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="room_id" value="<?= (int)$r['room_id'] ?>"><button style="border:0;background:none;color:#965d4e;cursor:pointer">Delete</button></form></td></tr><?php endforeach; ?></tbody></table><?php admin_end(); ?>
